import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

const Uploads = () => {
  const navigate = useNavigate();
  const [patientName, setPatientName] = useState("");
  const [patientId, setPatientId] = useState("");
  const [gender, setGender] = useState("Male");
  const [age, setAge] = useState("");
  const [date, setDate] = useState("");
  const [image, setImage] = useState(null);

  const handleImageChange = (e) => {
    if (e.target.files && e.target.files[0]) {
      setImage(URL.createObjectURL(e.target.files[0]));
    }
  };

  const handleScan = (e) => {
    e.preventDefault();
    if (!image) {
      alert("Please upload an image before scanning!");
      return;
    }
    navigate("/Analysis", {
      state: { patientName, patientId, gender, age, date, image },
    });
  };

  return (
    <div className="bg-lightgray text-black min-h-screen p-5 font-sans">
      <h1 className="text-3xl font-bold text-darkblue mb-6 text-center">
        Upload Medical Image
      </h1>

      {/* Image Upload Section */}
      <div className="mb-6 flex flex-col items-center">
        {image ? (
          <img
            src={image}
            alt="Uploaded"
            className="w-full max-w-md rounded-md border border-darkblue"
          />
        ) : (
          <div className="w-full max-w-md h-64 border-2 border-dashed border-darkblue flex items-center justify-center rounded-md bg-white">
            <p className="text-darkblue">No image uploaded</p>
          </div>
        )}
        <input
          type="file"
          accept="image/*"
          onChange={handleImageChange}
          className="mt-3 text-black"
        />
      </div>
      <h1 className="text-black"></h1>
      {/* Patient Info Form */}
      <form
        onSubmit={handleScan}
        className="max-w-md mx-auto flex flex-col gap-4 bg-white p-6 rounded-md shadow-md"
      >
        <input
          type="text"
          placeholder="Patient Name"
          value={patientName}
          onChange={(e) => setPatientName(e.target.value)}
          className="p-3 rounded-md border border-darkblue focus:outline-none focus:ring-2 focus:ring-darkblue"
          required
        />
        <input
          type="text"
          placeholder="Patient ID"
          value={patientId}
          onChange={(e) => setPatientId(e.target.value)}
          className="p-3 rounded-md border border-darkblue focus:outline-none focus:ring-2 focus:ring-darkblue"
          required
        />
        <select
          value={gender}
          onChange={(e) => setGender(e.target.value)}
          className="p-3 rounded-md border border-darkblue focus:outline-none focus:ring-2 focus:ring-darkblue"
        >
          <option value="Male">Male</option>
          <option value="Female">Female</option>
        </select>
        <input
          type="number"
          placeholder="Age"
          value={age}
          onChange={(e) => setAge(e.target.value)}
          className="p-3 rounded-md border border-darkblue focus:outline-none focus:ring-2 focus:ring-darkblue"
          required
        />
        <input
          type="date"
          value={date}
          onChange={(e) => setDate(e.target.value)}
          className="p-3 rounded-md border border-darkblue focus:outline-none focus:ring-2 focus:ring-darkblue"
          required
        />

        <button
          type="submit"
          className="bg-darkblue text-white font-semibold p-3 rounded-md hover:bg-blue-700 transition-colors"
        >
          Scan
        </button>
      </form>
    </div>
  );
};

export default Uploads;
